// scripts/build-admin-pages.mjs — bundles admin UI HTML/JS/CSS into a
// TypeScript module the Worker can serve at request time.
// Mirrors mountAdminPages (src/node/adminPages.ts) which is local-Node only.
// The generated file is committed to src/generated/ and regenerated on deploy.
//
// Reads source assets from:
//   src/auth-ui/*         (login page + login JS/CSS + sessions/devices)
//   dodumodu_site/dist/admin/index.html (console shell)
// Writes:
//   src/generated/adminPages.ts

import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'
import { createHash } from 'node:crypto'
import { patchConsoleJs } from './console-patch.mjs'
import { minifyJs, minifyCss, stripHtmlComments } from './minify-assets.mjs'

const __dirname = dirname(fileURLToPath(import.meta.url))
const backendRoot = resolve(__dirname, '..')
const repoRoot = resolve(backendRoot, '..')

const uiRoot = join(backendRoot, 'src', 'auth-ui')
const adminDistDir = join(repoRoot, 'dodumodu_site', 'dist', 'admin')
const siteDistDir = join(repoRoot, 'dodumodu_site', 'dist')
const OUT = join(backendRoot, 'src', 'generated', 'adminPages.ts')
// The console bundle AFTER patching but BEFORE minifying. Patching matches the bundle's own text and marker comments,
// which minifying removes, so this is what a build without the site project (dodumodu_site/dist) patches again.
const BASE = join(backendRoot, 'src', 'generated', 'console-bundle.base.js')

const read = (f) => readFileSync(join(uiRoot, f), 'utf8')
const readAdminDist = (f) => readFileSync(join(adminDistDir, f), 'utf8')
const lit = (k, v) => `export const ${k} = ${JSON.stringify(v)}\n`

// Ensure output dir exists
mkdirSync(dirname(OUT), { recursive: true })

// Public assets anyone may load (login page must render unauthenticated).
const loginHtml = stripHtmlComments(read('login.html')
  .replaceAll('/auth-ui/', '/admin/assets/'))

// Console shell + its hashed assets come from the site build (dodumodu_site/dist). When that build is not
// present (this backend checked out on its own), keep what the previous generated file already holds, so the
// auth-ui pages can still be regenerated without losing the console.
let consoleHtml, consoleAssets
if (existsSync(join(adminDistDir, 'index.html'))) {
  consoleHtml = readAdminDist('index.html')
  const consoleAssetNames = [
    ...consoleHtml.matchAll(/(?:href="|src=")\/(admin\.[^" ]+?\.(?:min\.css|min\.js))/g),
  ].map((match) => match[1])
  consoleAssets = Object.fromEntries(
    consoleAssetNames.map((name) => [name, readFileSync(join(siteDistDir, name), 'utf8')]),
  )
} else if (existsSync(OUT)) {
  const prev = await import(pathToFileURL(OUT).href + '?t=' + Date.now())
  consoleHtml = prev.ADMIN_CONSOLE_HTML
  consoleAssets = { ...prev.ADMIN_CONSOLE_ASSETS }
  const prevJs = Object.keys(consoleAssets).find((n) => /\.min\.js$/.test(n))
  if (prevJs && existsSync(BASE)) consoleAssets[prevJs] = readFileSync(BASE, 'utf8')
  console.warn('site build not found: kept the console shell + assets from the existing generated file')
} else {
  throw new Error('No site build (dodumodu_site/dist/admin) and no previous generated file to reuse')
}

// Fixes for the console bundle (see scripts/console-patch.mjs). Applied to the JS asset on every build; when the
// content changes the asset gets a new hashed name so browsers and the edge never serve the unpatched copy.
{
  const jsName = Object.keys(consoleAssets).find((n) => /\.min\.js$/.test(n))
  if (jsName) {
    // Patch first (the patches match the bundle's own names), minify last, hash what is actually served.
    const patchedSource = patchConsoleJs(consoleAssets[jsName])
    writeFileSync(BASE, patchedSource)
    const patched = minifyJs(patchedSource)
    {
      const hash = createHash('sha1').update(patched).digest('hex').slice(0, 8)
      const newName = jsName.replace(/^(admin\.)[^.]+(\.min\.js)$/, `$1${hash}$2`)
      delete consoleAssets[jsName]
      consoleAssets[newName] = patched
      consoleHtml = consoleHtml.split(jsName).join(newName)
    }
  }
}

const out =
  `// GENERATED by scripts/build-admin-pages.mjs, do not edit\n` +
  `// Admin UI assets bundled for the Cloudflare Worker.\n` +
  lit('ADMIN_LOGIN_HTML', loginHtml) +
  lit('ADMIN_AUTH_CSS', minifyCss(read('auth.css'))) +
  lit('ADMIN_AUTH_JS', minifyJs(read('auth.js'))) +
  lit('ADMIN_ADMIN_CSS', minifyCss(read('auth.css'))) +
  lit('ADMIN_CONSOLE_HTML', consoleHtml) +
  lit('ADMIN_CONSOLE_ASSETS', consoleAssets) +
  lit('ADMIN_SESSIONS_HTML', stripHtmlComments(read('sessions.html')
    .replaceAll('/auth-ui/', '/admin/assets/'))) +
  lit('ADMIN_SESSIONS_JS', minifyJs(read('sessions.js'))) +
  lit('ADMIN_DEVICES_HTML', stripHtmlComments(read('devices.html')
    .replaceAll('/auth-ui/', '/admin/assets/'))) +
  lit('ADMIN_DEVICES_JS', minifyJs(read('devices.js'))) +
  lit('ADMIN_UI_JS', minifyJs(read('admin-ui.js'))) +
  lit('ADMIN_DEVICE_ACCEPT_HTML', stripHtmlComments(read('device-accept.html')
    .replaceAll('/auth-ui/', '/admin/assets/'))) +
  lit('ADMIN_DEVICE_ACCEPT_JS', minifyJs(read('device-accept.js'))) +
  lit('ADMIN_QR_JS', minifyJs(read('qr.js'))) +
  lit('ADMIN_QR_LOGO_MJS', minifyJs(read('qr-logo.mjs'), { module: true }))

writeFileSync(OUT, out)

console.log(`built ${OUT}`)
console.log(`  admin login page, console shell, sessions, devices, assets`)